    df=pd.read_csv(eval(f"experiment_{i}_csv"))
    if 'do_ElectrolyteAdditive' in df:
        sub=df[['CapacityRetention','do_ElectrolyteAdditive']].copy()
        if 'do_FormationCurrent' in df:
            sub['FC']=df['do_FormationCurrent']
        else:
            sub['FC']=np.nan
        frames.append(sub)
